import{_ as s,o as i,c as e,a2 as t}from"./chunks/framework.BHRgmlt_.js";const k=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md","lastUpdated":1786256529000}'),n={name:"faq.md"};function o(l,a,h,d,p,r){return i(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="部署" tabindex="-1">部署 <a class="header-anchor" href="#部署" aria-label="Permalink to &quot;部署&quot;">​</a></h2><h3 id="宿主机访问不了容器" tabindex="-1">宿主机访问不了容器 <a class="header-anchor" href="#宿主机访问不了容器" aria-label="Permalink to &quot;宿主机访问不了容器&quot;">​</a></h3><p><strong>现象</strong>:宿主机 ping / curl 不通 <code>192.168.3.100</code>。</p><p><strong>原因</strong>:macvlan 同端口隔离。容器 macvlan 挂在宿主主网卡(eth0)上时,宿主机访问被内核丢弃。</p><p><strong>处理</strong>:</p><ol><li>确认 macvlan parent 是第二网口(<code>yacd network</code> 检查)</li><li>若 parent 是 eth0,按<a href="/yacd/docs/guide/deployment.html">部署指南</a>改用 USB 网卡</li><li>验证用 <code>curl</code>,不要用 <code>ping</code>(宿主可能缺 <code>cap_net_raw</code>)</li></ol><h3 id="宿主机-ping-报-cap-net-raw-错误" tabindex="-1">宿主机 ping 报 <code>cap_net_raw</code> 错误 <a class="header-anchor" href="#宿主机-ping-报-cap-net-raw-错误" aria-label="Permalink to &quot;宿主机 ping 报 `cap_net_raw` 错误&quot;">​</a></h3><p>非 root 用户 <code>ping</code> 可能报 <code>Operation not permitted</code>(缺原始套接字权限)。用 <code>curl</code>/<code>wget</code> 验证。</p><h3 id="macvlan-网络创建失败" tabindex="-1">macvlan 网络创建失败 <a class="header-anchor" href="#macvlan-网络创建失败" aria-label="Permalink to &quot;macvlan 网络创建失败&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Error response from daemon: Pool overlaps with other one on this address space</span></span></code></pre></div><p>同一子网已存在其他 macvlan 网络。删除旧的再建:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> network</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">旧网</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">络</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yacd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span></span></code></pre></div><h3 id="public-index-html-缺失" tabindex="-1"><code>public/index.html</code> 缺失 <a class="header-anchor" href="#public-index-html-缺失" aria-label="Permalink to &quot;`public/index.html` 缺失&quot;">​</a></h3><p><strong>现象</strong>:<code>yacd up</code> 报找不到前端产物。</p><p><strong>处理</strong>:本地构建后上传:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> public/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">use</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">@</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">na</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">s</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:~/.yacd/</span></span></code></pre></div><h2 id="代理" tabindex="-1">代理 <a class="header-anchor" href="#代理" aria-label="Permalink to &quot;代理&quot;">​</a></h2><h3 id="_7890-端口连不上" tabindex="-1">7890 端口连不上 <a class="header-anchor" href="#_7890-端口连不上" aria-label="Permalink to &quot;7890 端口连不上&quot;">​</a></h3><p><strong>现象</strong>:局域网设备手动配代理 <code>192.168.3.100:7890</code> 连接失败。</p><p><strong>原因</strong>:<code>mixed-port</code> 默认绑 <code>127.0.0.1</code>(仅容器内)。</p><p><strong>处理</strong>:配置 <code>bind-address: 0.0.0.0</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yacd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> edit</span></span></code></pre></div><h3 id="流量不走代理-日志看不到客户端" tabindex="-1">流量不走代理 / 日志看不到客户端 <a class="header-anchor" href="#流量不走代理-日志看不到客户端" aria-label="Permalink to &quot;流量不走代理 / 日志看不到客户端&quot;">​</a></h3><p><strong>现象</strong>:目标容器改了网关但 mihomo 日志无记录。</p><p><strong>处理</strong>:</p><ol><li>目标容器需 <code>--cap-add NET_ADMIN</code> 才能改路由</li><li>确认 <code>ip route</code> 默认网关是 <code>192.168.3.100</code></li><li>目标容器与 mihomo 容器须在同一 macvlan 网络</li></ol><h3 id="设备拿到-fake-ip-但连不上" tabindex="-1">设备拿到 Fake-IP 但连不上 <a class="header-anchor" href="#设备拿到-fake-ip-但连不上" aria-label="Permalink to &quot;设备拿到 Fake-IP 但连不上&quot;">​</a></h3><p><strong>现象</strong>:DNS 解析返回 198.18.x.x,但流量没走 mihomo。</p><p><strong>原因</strong>:只改了 DNS,没把网关指向 mihomo。</p><p><strong>处理</strong>:网关 + DNS <strong>同时</strong>指向 <code>192.168.3.100</code>。</p><h2 id="系统" tabindex="-1">系统 <a class="header-anchor" href="#系统" aria-label="Permalink to &quot;系统&quot;">​</a></h2><h3 id="nas-改网络模式后失联" tabindex="-1">NAS 改网络模式后失联 <a class="header-anchor" href="#nas-改网络模式后失联" aria-label="Permalink to &quot;NAS 改网络模式后失联&quot;">​</a></h3><p><strong>现象</strong>:控制面板 → 网络 → 网络模式改动后,ping 通但 Web/SSH 无响应。</p><p><strong>处理</strong>:NAS 机身上短按 Reset 重置网络(不丢数据),或电源重启。</p><p><strong>教训</strong>:不要轻易改 UGOS 网络模式;本方案只创建 Docker 网络,不动系统网络。</p><h3 id="nas-重启后容器没自动恢复" tabindex="-1">NAS 重启后容器没自动恢复 <a class="header-anchor" href="#nas-重启后容器没自动恢复" aria-label="Permalink to &quot;NAS 重启后容器没自动恢复&quot;">​</a></h3><p>检查容器是否设置了 <code>restart: unless-stopped</code>(compose 已内置)。若手动 <code>docker run</code> 创建的旧容器,需先用 <code>yacd up</code> 接管(数据卷保留)。</p><h3 id="eth1-的-ip-变了" tabindex="-1">eth1 的 IP 变了 <a class="header-anchor" href="#eth1-的-ip-变了" aria-label="Permalink to &quot;eth1 的 IP 变了&quot;">​</a></h3><p>UGOS 重新 DHCP 分配,属正常。macvlan 容器 IP 是 <code>--ip</code> 指定的固定值,不受影响。</p><h2 id="更新" tabindex="-1">更新 <a class="header-anchor" href="#更新" aria-label="Permalink to &quot;更新&quot;">​</a></h2><h3 id="yacd-update-下载失败" tabindex="-1"><code>yacd update</code> 下载失败 <a class="header-anchor" href="#yacd-update-下载失败" aria-label="Permalink to &quot;`yacd update` 下载失败&quot;">​</a></h3><p><strong>现象</strong>:解析不到 release 或下载失败。</p><p><strong>处理</strong>:</p><ul><li>release 尚未发布(首次)时,用开发分支: <code>YACD_USE_MAIN=1 yacd update</code></li><li>网络受限时检查 GitHub 可达性</li></ul>',45)])])}const g=s(n,[["render",o]]);export{k as __pageData,g as default};
